INSERT INTO `DesignSample` VALUES ('cmsx5vxad0000jepntsm78m3q','PHÒNG NGỦ KHÔNG CÓ CỬA SỔ – TOP CÁCH KHẮC PHỤC HẠN CHẾ CỦA THIẾT KẾ HIỆU QUẢ NHẤT','khac-phuc-han-che-phong-ngu-khong-cua-so','livingRoom','Phòng khách','Đa phong cách',NULL,'https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/design-samples/khac-phuc-han-che-phong-ngu-khong-cua-so/cover-001-001-01-pn2-cam01-022672a0.webp','Tình trạng phòng ngủ không có cửa sổ do lối thiết kế kiến trúc nhà ở được xây dựng hàng loạt tại các thành phố lớn gây ra sự ngột ngạt, bó bách, không được hứng ánh nắng từ bên ngoài, cũng như ánh sáng tự nhiên làm mất sự thoải mái cho người sử [&hellip;]',1,0,'published','2026-08-17 11:39:46.868','2026-08-17 11:39:46.885','2026-08-17 11:39:51.380'),('cmsx5vxau000hjepn3ytxxz94','3 BẢNG MÀU KÍNH ỐP BẾP SANG TRỌNG – TẠO SỰ HÀI HÒA CHO MỌI THIẾT KẾ TỦ BẾP','3-bang-mau-kinh-op-bep-cho-moi-thiet-ke-tu-bep','kitchen','Phòng bếp','Hiện đại',NULL,'https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/design-samples/3-bang-mau-kinh-op-bep-cho-moi-thiet-ke-tu-bep/cover-001-001-01-phong-bep-1-2-0bc42770.webp','Để tăng thêm điểm nhấn cho tủ bếp và tạo sự sang trọng cho toàn bộ ngôi nhà, ở các kiến trúc hiện đại thay vì sử dụng những loại gạch ốp tường truyền thống như gạch ốp, gỗ ốp tường,… có nhiều hạn chế thì nhiều gia đình đã lựa chọn kính với màu [&hellip;]',1,1,'published','2026-08-17 11:39:46.900','2026-08-17 11:39:46.902','2026-08-17 11:39:52.879'),('cmsx5vxbq000wjepnhbo1xy44','TỔNG HỢP 40+ MẪU TỦ BẾP TIỆN NGHI “VẠN NGƯỜI MÊ” – ĐỪNG BỎ LỠ XU HƯỚNG MỚI NHẤT NĂM 2023','tong-hop-40-mau-tu-bep-tien-nghi-2023','kitchen','Phòng bếp','Đa phong cách',NULL,'https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/design-samples/tong-hop-40-mau-tu-bep-tien-nghi-2023/cover-001-001-01-image-cd545b1f.webp','Bạn đang phân vân không biết lựa chọn thiết kế mẫu tủ bếp như thế nào cho phù hợp? Bếp là nơi “giữ lửa” cho cả gia đình bạn, một căn bếp đẹp, đáp ứng đủ các nhu cầu cần thiết là đi