INSERT INTO `DesignSampleDetail` VALUES ('cmsx5vxag0001jepniey0vsfq','cmsx5vxad0000jepntsm78m3q','Mẫu thiết kế phòng khách','Mẫu thiết kế','PHÒNG NGỦ KHÔNG CÓ CỬA SỔ – TOP CÁCH KHẮC PHỤC HẠN CHẾ CỦA THIẾT KẾ HIỆU QUẢ NHẤT','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/design-samples/khac-phuc-han-che-phong-ngu-khong-cua-so/cover-001-001-01-pn2-cam01-022672a0.webp','Tình trạng phòng ngủ không có cửa sổ do lối thiết kế kiến trúc nhà ở được xây dựng hàng loạt tại các thành phố lớn gây ra sự ngột ngạt, bó bách, không được hứng ánh nắng từ bên ngoài, cũng như ánh sáng tự nhiên làm mất sự thoải mái cho người sử [&hellip;]','Phòng khách',NULL,NULL,NULL,'Tham khảo theo nhu cầu thực tế','Không gian được gợi mở từ nhu cầu sử dụng','[\"Tình trạng phòng ngủ không có cửa sổ do lối thiết kế kiến trúc nhà ở được xây dựng hàng loạt tại các thành phố lớn gây ra sự ngột ngạt, bó bách, không được hứng ánh nắng từ bên ngoài, cũng như ánh sáng tự nhiên làm mất sự thoải mái cho người sử [&hellip;]\", \"Hình ảnh được chọn lọc từ thư viện website cũ và sẽ tiếp tục được biên tập theo nhu cầu triển khai thực tế.\"]',NULL,'PHÒNG NGỦ KHÔNG CÓ CỬA SỔ – TOP CÁCH KHẮC PHỤC HẠN CHẾ CỦA THIẾT KẾ HIỆU QUẢ NHẤT | Tổ Ấm Hoàn Hảo','Tình trạng phòng ngủ không có cửa sổ do lối thiết kế kiến trúc nhà ở được xây dựng hàng loạt tại các thành phố lớn gây ra sự ngột ngạt, bó bách, không được hứng ánh nắng từ bên ngoài, cũng như ánh sáng tự nhiên làm mất sự thoải mái cho người sử [&hellip;]'),('cmsx5vxav000ijepnq5etq5i2','cmsx5vxau000hjepn3ytxxz94','Mẫu thiết kế phòng bếp','Mẫu thiết kế','3 BẢNG MÀU KÍNH ỐP BẾP SANG TRỌNG – TẠO SỰ HÀI HÒA CHO MỌI THIẾT KẾ TỦ BẾP','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/design-samples/3-bang-mau-kinh-op-bep-cho-moi-thiet-ke-tu-bep/cover-001-001-01-phong-bep-1-2-0bc42770.webp','Để tăng thêm điểm nhấn cho tủ bếp và tạo sự sang trọng cho toàn bộ ngôi nhà, ở các kiến trúc hiện đại thay vì sử dụng những loại gạch ốp tường truyền thống như gạch ốp, gỗ ốp tường,… có nhiều hạn chế thì nhiều gia đình đã lựa chọn kính với màu [&hellip;]','Phòng bếp',NULL,NULL,NULL,'Tham khảo theo nhu cầu thực tế','Không gian được gợi mở từ nhu cầu sử dụng','[\"Để tăng thêm điểm nhấn cho tủ bếp và tạo sự sang trọng cho toàn bộ ngôi nhà, ở các kiến trúc hiện đại thay vì sử dụng những loại gạch ốp tường truyền thống như gạch ốp, gỗ ốp tường,… có nhiều hạn chế thì nhiều gia đình đã lựa chọn kính với màu [&hellip;]\", \"Hình ảnh được chọn lọc từ thư viện website cũ và sẽ tiếp tục được biên tập theo nhu cầu triển khai thực tế.\"]',NULL,'3 BẢNG MÀU KÍNH ỐP BẾP SANG TRỌNG – TẠO SỰ HÀI HÒA CHO MỌI THIẾT KẾ TỦ BẾP | Tổ Ấm Hoàn Hảo','Để tăng thêm điểm nhấn cho tủ bếp và tạo sự sang trọng cho toàn bộ ngôi nhà, ở các kiến trúc hiện đại thay vì sử dụng những loại gạch ốp tường truyền thống như gạch ốp, gỗ ốp tường,… có nhiều hạn chế thì nhiều gia đình đã lựa chọn kính với màu [&hellip;]'),('cmsx5vxbr000xjepnk0kjx4db','cmsx5vxbq000wjepnhbo1xy44','Mẫu thiết kế phòng bếp','Mẫu thiết kế','TỔNG HỢP 40+ MẪU TỦ BẾP TIỆN NGHI “VẠN NGƯỜI MÊ” – ĐỪNG BỎ LỠ XU HƯỚNG MỚI NHẤT NĂM 2023','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/design-samples/tong-hop-40-mau-tu-bep-tien-nghi-2023/cover-001-001-01-image-cd545b1f.webp','Bạn đang phân vân không biết lựa chọn thiết kế mẫu tủ bếp như thế nào cho phù hợp? Bếp là nơi “giữ lửa” cho cả gia đình bạn, một căn bếp đẹp, đáp ứng đủ các nhu cầu cần thiết là điều không thể thiếu trong mỗi căn nhà. Tổ ấm hoàn hảo là [&hellip;]','Phòng bếp',NULL,NULL,NULL,'Tham khảo theo nhu cầu thực tế','Không gian được gợi mở từ nhu cầu sử dụng','[\"Bạn đang phân vân không biết lựa chọn thiết kế mẫu tủ bếp như thế nào cho phù hợp? Bếp là nơi “giữ lửa” cho cả gia đình bạn, một căn bếp đẹp, đáp ứng đủ các nhu cầu cần thiết là điều không thể thiếu trong mỗi căn nhà. Tổ ấm hoàn hảo là [&hellip;]\", \"Hình ảnh được chọn lọc từ thư viện website cũ và sẽ tiếp tục được biên tập theo nhu cầu triển khai thực tế.\"]',NULL,'TỔNG HỢP