  `relatedSampleId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sortOrder` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `DesignSampleRelated_sampleId_relatedSampleId_key` (`sampleId`,`relatedSampleId`),
  KEY `DesignSampleRelated_sampleId_sortOrder_idx` (`sampleId`,`sortOrder`),
  KEY `DesignSampleRelated_relatedSampleId_idx` (`relatedSampleId`),
  CONSTRAINT `DesignSampleRelated_relatedSampleId_fkey` FOREIGN KEY (`relatedSampleId`) REFERENCES `DesignSample` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `DesignSampleRelated_sampleId_fkey` FOREIGN KEY (`sampleId`) REFERENCES `DesignSample` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
