INSERT INTO `ProjectDetail` VALUES ('cmsrdxrnr0001z0pnlta08pqu','cmsrdxrnk0000z0pnnfvxzdrw','Dự án nội thất','Test Database','Project','https://images.unsplash.com/photo-1616046229478-9901c5536a45?auto=format&fit=crop&w=900&q=85','Bản nháp được tạo bằng server action.',NULL,NULL,'8 tuần','Thiết kế & thi công nội thất','Tổng quan test','[\"Nội dung tổng quan test.\"]',NULL,NULL,NULL),('cmsrsdxvi0005z0pnm82q0wd2','cmsrsdxvc0004z0pn06vicbjt','Dự án căn hộ','Test Project','With Blocks Edited','https://images.unsplash.com/photo-1616046229478-9901c5536a45?auto=format&fit=crop&w=900&q=85','Bản nháp đã edit.',NULL,NULL,'7 tuần','Thiết kế nội thất','Tổng quan dự án edit','[\"Nội dung tổng quan edit.\"]',NULL,NULL,NULL),('cmsrtzev8007wz0pndzzqvd2h','cmsrtzev7007vz0pnn9an1img','Dự án căn hộ','Căn hộ','The Matrix One','https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1600&q=85','Không gian sống hiện đại, tinh tế và ấm áp, được thiết kế dành riêng cho gia đình trẻ yêu thích sự tối giản và tiện nghi.','2 phòng ngủ','2','8 tuần','Thiết kế & thi công nội thất','Không gian sống đủ đầy và kết nối','[\"Gia chủ là một cặp vợ chồng trẻ cùng con nhỏ, mong muốn một tổ ấm hiện đại, ấm áp và thật nghỉ để cân bằng giữa công việc và cuộc sống.\", \"Thiết kế hướng đến sự tinh giản về hình thức, tối ưu công năng, khai thác ánh sáng tự nhiên và sử dụng chất liệu bền vững để mang lại cảm giác thư thái, gắn kết cho cả gia đình.\"]','/floor-plan-matrix-one.svg','Căn hộ The Matrix One | Tổ Ấm Hoàn Hảo','Dự án thiết kế và thi công nội thất căn hộ The Matrix One 120m² theo phong cách Modern Luxury.'),('cmsrtzevt008jz0pnnwr7douk','cmsrtzevs008iz0pn1sc5dyb7','Căn hộ','Vinhomes Ocean Park','','https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=900&q=85','Thiết kế căn hộ gọn gàng với chất liệu sáng, mềm và nhiều ánh sáng tự nhiên.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Vinhomes Ocean Park','[\"Thiết kế căn hộ gọn gàng với chất liệu sáng, mềm và nhiều ánh sáng tự nhiên.\"]',NULL,NULL,NULL),('cmsrtzew0008tz0pnjp2vxfu2','cmsrtzew0008sz0pnqb4g07m8','Biệt thự','Biệt thự Riverside','','https://images.unsplash.com/photo-1600566753376-12c8ab7fb75b?auto=format&fit=crop&w=900&q=85','Biệt thự với không gian sinh hoạt mở, kết nối phòng khách, bếp và sân vườn.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Biệt thự Riverside','[\"Biệt thự với không gian sinh hoạt mở, kết nối phòng khách, bếp và sân vườn.\"]',NULL,NULL,NULL),('cmsrtzew70093z0pn3lhcglat','cmsrtzew70092z0pnym49oryc','Nhà phố','Nhà phố Modern Garden','','https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=900&q=85','Nhà phố hiện đại với mảng xanh và khoảng thông tầng tạo cảm giác thoáng đãng.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Nhà phố Modern Garden','[\"Nhà phố hiện đại với mảng xanh và khoảng thông tầng tạo cảm giác thoáng đãng.\"]',NULL,NULL,NULL),('cmsrtzewd009dz0pnd7zjvpw2','cmsrtzewd009cz0pn7fd66gol','Nội thất trọn gói','Penthouse West Lake','','https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1200&q=85','Không gian penthouse sang trọng với tầm nhìn panorama hồ Tây, kết hợp chất liệu cao cấp và nghệ thuật ánh sáng.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Penthouse West Lake','[\"Không gian penthouse sang trọng với tầm nhìn panorama hồ Tây, kết hợp chất liệu cao cấp và nghệ thuật ánh sáng.\"]',NULL,NULL,NULL),('cmsrtzewj009nz0pnwfro6nz1','cmsrtzewj009mz0pn9lcg2274','Văn phòng','Văn phòng Elegant Hub','','https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=900&q=85','Văn phòng sáng, linh hoạt, tối ưu khu làm việc nhóm và phòng họp riêng.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Văn phòng Elegant Hub','[\"Văn phòng sáng, linh hoạt, tối ưu khu làm việc nhóm và phòng họp riêng.\"]',NULL,NULL,NULL),('cmsrtzewo009xz0pnwglozrtj','cmsrtzewn009wz0pnojgqttg1','Căn hộ','Căn hộ Sun Grand City','','https://images.unsplash.com/photo-1600566752355-35792bedcfea?auto=format&fit=crop&w=900&q=85','Căn hộ tông gỗ ấm, xử lý lưu trữ thông minh và bếp mở thân thiện.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Căn hộ Sun Grand City','[\"Căn hộ tông gỗ ấm, xử lý lưu trữ thông minh và bếp mở thân thiện.\"]',NULL,NULL,NULL),('cmsrtzewt00a7z0pnueldw41m','cmsrtzews00a6z0pndmvfpxbd','Biệt thự','Biệt thự Green Villa','','https://images.unsplash.com/photo-1613977257363-707ba9348227?auto=format&fit=crop&w=900&q=85','Không gian biệt thự nghỉ dưỡng tại gia, cân bằng giữa riêng tư và kết nối.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Biệt thự Green Villa','[\"Không gian biệt thự nghỉ dưỡng tại gia, cân bằng giữa riêng tư và kết nối.\"]',NULL,NULL,NULL),('cmsrtzewx00ahz0pnae9g58uj','cmsrtzewx00agz0pne9yznr0l','Nhà phố','Nhà phố Harmony House','','https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=900&q=85','Nhà phố nhẹ nhàng với màu trung tính, ánh sáng tự nhiên và nội thất tinh gọn.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Nhà phố Harmony House','[\"Nhà phố nhẹ nhàng với màu trung tính, ánh sáng tự nhiên và nội thất tinh gọn.\"]',NULL,NULL,NULL),('cmsrtzex300arz0pn892o5mwl','cmsrtzex200aqz0pn1tjhkjp8','Văn phòng','Văn phòng Creative Space','','https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=900&q=85','Không gian làm việc mở cho đội ngũ sáng tạo, có lounge và khu brainstorm.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Văn phòng Creative Space','[\"Không gian làm việc mở cho đội ngũ sáng tạo, có lounge và khu brainstorm.\"]',NULL,NULL,NULL),('cmsrtzex700b1z0pnojso5gy0','cmsrtzex700b0z0pnw70fg6ll','Căn hộ','Căn hộ Lumière Riverside','','https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=900&q=85','Căn hộ sáng và mềm, tập trung trải nghiệm sinh hoạt gia đình hằng ngày.',NULL,NULL,NULL,'Thiết kế & thi công nội thất','Căn hộ Lumière Riverside','[\"Căn hộ sáng và mềm, tập trung trải nghiệm sin