INSERT INTO `ProjectStoryBlock` VALUES ('cmsrsexux000bz0pnh21ytef0','cmsrsdxvc0004z0pn06vicbjt','01','Không gian edit','Mô tả block edit.','https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1200&q=85','left',0),('cmsrtzk2t00i9z0pn8bvgbeis','cmsrtzev7007vz0pnn9an1img','01','Phòng khách','Ánh sáng tự nhiên tràn ngập qua hệ cửa kính lớn, kết hợp cùng tông màu be ấm và chất liệu gỗ tự nhiên, mang đến không gian mở, thư thái và gắn kết.','https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1200&q=85','right',0),('cmsrtzk2t00iaz0png33uyxs3','cmsrtzev7007vz0pnn9an1img','03','Phòng ngủ master','Dấu giường ốp gỗ kết hợp vải nỉ, ánh sáng dịu nhẹ và tủ âm tường tối ưu lưu trữ, tạo nên không gian nghỉ ngơi yên tĩnh và thư giãn tuyệt đối.','https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1200&q=85','left',1),('cmsrtzk2t00ibz0pnavlk61lj','cmsrtzev7007vz0pnn9an1img','02','Bếp & khu vực ăn','Tủ bếp gọn gàng, thiết bị hiện đại và bàn ăn ấm cúng giúp mọi bữa cơm trở thành khoảnh khắc sum vầy, kết nối yêu thương.','https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1200&q=85','right',2),('cmswx0vxt000ljypnuke59dhv','cmswx0vxi0000jypnn15q8whv','01','Phong cách thiết kế','Biệt thự Vinhomes nhà chị Huyền có diện tích ở mức trung, việc bố trí không gian hợp lý không phải thử thách quá khó khăn. Khi tiến hành trao đổi, chị Huyền có yêu cầu không gian thiết kế mang phong cách tân cổ điển nhưng có một chút hơi hướng trẻ trung, nổi bật, sang trọng, ấn tượng nhưng vẫn phải nhã nhặn và đầy tinh tế.\n\nTheo yêu cầu từ phía gia chủ, không gian tổng thể được thiết kế mang hơi hướng tân cổ điển nhưng không nặng nề về đường nét, các chi tiết, hoa văn được tiết chế để tạo vẻ đẹp nhẹ nhàng và trẻ trung. Màu sắc chủ đạo được lựa chọn là trắng và vàng kim – cặp đôi màu sắc đặc trưng của phong cách tân cổ điển, kết hợp với nội thất màu nâu da bò đậm. Sự kết hợp màu sắc tinh tế tạo nên một tổng thể hài hòa, sang trọng nhưng đầy ấm cúng.\n\nĐiểm nổi bật của thiết kế này chính là cách bố trí các không gian lưu trữ đồ đạc cực gọn gàng và thông minh. Bức tường ngăn giữa phòng ăn và bếp được khéo léo biến tấu thành những hộc tủ âm tường để trưng bày đồ trang trí, vừa tiết kiệm lại mang lại hiệu quả trang trí cho cả hai không gian. Các đồ nội thất trong phòng bếp hay phòng thay đồ cũng được thiết kế vô cùng tinh tế và thông minh, vừa đẹp mắt lại giải quyết vấn đề lưu trữ đồ một cách gọn gàng nhất.\n\nMột điểm sáng khác trong thiết kế chính là việc bố trí ánh sáng khoa học, tạo nên những hiệu ứng thú vị về thị giác, cho không gian vẻ thoáng sáng, lung linh, cực sang trọng và thu hút. Sử dụng ánh sáng vàng để tạo cảm giác dịu nhẹ, ấm cúng. Đồng thời, đèn được bố trí rất khéo léo ở những vị trí cần làm nổi bật như các hộc tủ bày đồ trang trí, bàn ăn,… Tất cả phối hợp tạo nên một tổng thể cực ấn tượng và đẹp mắt.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/cover-01-01-01-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-1-acde3114.webp','right',0),('cmswx0vxt000mjypnefz9kl8j','cmswx0vxi0000jypnn15q8whv','02','Phong cách thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/gallery-02-02-02-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-2-54ad7c90.webp','left',1),('cmswx0vxt000njypn8v2faaxe','cmswx0vxi0000jypnn15q8whv','03','Phong cách thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/gallery-03-03-03-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-3-69b06411.webp','right',2),('cmswx0vxt000ojypnke8yduqf','cmswx0vxi0000jypnn15q8whv','04','Phong cách thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/gallery-04-04-04-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-4-f6c400b6.webp','left',3),('cmswx0vxu000pjypnn6xupl61','cmswx0vxi0000jypnn15q8whv','05','Phong cách thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/gallery-05-05-05-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-5-67487d13.webp','right',4),('cmswx0vxu000qjypnrntxcbwn','cmswx0vxi0000jypnn15q8whv','06','Phong cách thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/gallery-06-06-06-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-6-4654e21d.webp','left',5),('cmswx0vxu000rjypnxmjm1wk4','cmswx0vxi0000jypnn15q8whv','07','Phong cách thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/gallery-07-07-07-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-7-cab8ec0e.webp','right',6),('cmswx0vxu000sjypn5b115kar','cmswx0vxi0000jypnn15q8whv','08','Phong cách thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/gallery-08-08-08-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-8-7d17c6b7.webp','left',7),('cmswx0vxu000tjypn2999yuog','cmswx0vxi0000jypnn15q8whv','09','Phong cách thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/gallery-09-09-09-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-9-0d13a7d0.webp','right',8),('cmswx0vxu000ujypng7eqmtrt','cmswx0vxi0000jypnn15q8whv','10','Phong cách thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/cong-trinh-biet-thu-vinhomes-riverside-tieu-khu-phong-lan/gallery-10-10-10-thiet-ke-thi-cong-kien-truc-noi-that-chi-huyen-vinhomes-riveside-10-ee1bedad.webp','left',9),('cmswx10bf000kl1pndtk6qltl','cmswx10b70000l1pnhd7m52ky','01','Câu chuyện thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-anh-hung-biet-thu-nha-vuon-bac-ninh/cover-01-01-01-thiet-ke-noi-that-biet-thu-nha-vuon-bac-ninh-anh-hung-6-bbc49a14.webp','right',0),('cmswx10bf000ll1pnyxeygtew','cmswx10b70000l1pnhd7m52ky','02','Câu chuyện thiết kế','Không gian mang đậm hơi hướng tân cổ điển, phong cách hoàng gia sang trọng và ấn tượng.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-anh-hung-biet-thu-nha-vuon-bac-ninh/gallery-02-02-02-thiet-ke-noi-that-biet-thu-nha-vuon-bac-ninh-anh-hung-7-07d708be.webp','left',1),('cmswx10bf000ml1pnjh8ew0s5','cmswx10b70000l1pnhd7m52ky','03','Câu chuyện thiết kế','Tất cả nội thất từ sofa đến bàn ghế ăn,… đều được đặt thiết kế và gia công thủ công theo yêu cầu của gia chủ tại xưởng sản xuất của công ty PHL, đảm bảo sự phù hợp hoàn hảo khi đặt vào không gian.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-anh-hung-biet-thu-nha-vuon-bac-ninh/gallery-03-03-03-thiet-ke-noi-that-biet-thu-nha-vuon-bac-ninh-anh-hung-9-c2f35aad.webp','right',2),('cmswx10bf000nl1pn3d8iypb8','cmswx10b70000l1pnhd7m52ky','04','Câu chuyện thiết kế','Sofa sang trọng với các hoa văn gỗ sồi phủ sơn tĩnh điện được gia công tỉ mỉ và cầu kỳ, bọc nỉ cao cấp vô cùng đẹp mắt.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-anh-hung-biet-thu-nha-vuon-bac-ninh/gallery-04-04-04-thiet-ke-noi-that-biet-thu-nha-vuon-bac-ninh-anh-hung-4-61759216.webp','left',3),('cmswx10bf000ol1pntdjepjg6','cmswx10b70000l1pnhd7m52ky','05','Câu chuyện thiết kế','Góc ban thờ nhỏ nhắn nhưng được trang hoàng bằng những món đồ thờ đẹp mắt. Chất liệu chủ yếu được sử dụng là gỗ và đồng, phù hợp với không gian thờ cúng trang nghiêm.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-anh-hung-biet-thu-nha-vuon-bac-ninh/gallery-05-05-05-thiet-ke-noi-that-biet-thu-nha-vuon-bac-ninh-anh-hung-5-cace0d8f.webp','right',4),('cmswx10bf000pl1pn7t6s6ucd','cmswx10b70000l1pnhd7m52ky','06','Câu chuyện thiết kế','Một góc khác đặt ban thờ nhỏ được điêu khắc khá tỉ mỉ. Tranh trang trí tone màu trầm và đồng hồ đứng giả cổ vô cùng phù hợp với không gian cổ điển sang trọng.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-anh-hung-biet-thu-nha-vuon-bac-ninh/gallery-06-06-06-thiet-ke-noi-that-biet-thu-nha-vuon-bac-ninh-anh-hung-2-5a119c7a.webp','left',5),('cmswx10bf000ql1pn9605kkj8','cmswx10b70000l1pnhd7m52ky','07','Câu chuyện thiết kế','Trong khu vực sảnh phòng khách có một không gian trưng bày những chiếc đồng hồ giả cổ vô cùng ấn tượng. Từ chiếc tủ được trang trí cầu kỳ đến những chiếc đồng hồ đẹp mắt đều toát lên vẻ cổ điển, sang trọng và ấn tượng, cho không gian thêm thu hút.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-anh-hung-biet-thu-nha-vuon-bac-ninh/gallery-07-07-07-thiet-ke-noi-that-biet-thu-nha-vuon-bac-ninh-anh-hung-1-36eb4ce1.webp','right',6),('cmswx10bf000rl1pn8300p8iv','cmswx10b70000l1pnhd7m52ky','08','Câu chuyện thiết kế','Phòng ăn sang trọng. Từng chi tiết nhỏ như hộp giấy ăn đều được chọn lựa kĩ càng cho thật hài hòa và phù hợp với không gian.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-anh-hung-biet-thu-nha-vuon-bac-ninh/gallery-08-08-08-thiet-ke-noi-that-biet-thu-nha-vuon-bac-ninh-anh-hung-8-4d4b61cd.webp','left',7),('cmswx10bf000sl1pnt4kedyxv','cmswx10b70000l1pnhd7m52ky','09','Câu chuyện thiết kế','Không gian bếp tiện nghi vói nội thất trắng sang trọng được trang trí bằng những chi tiết mạ vàng đẹp mắt. Phần trần nhà cũng được gia công vô cùng cầu kỳ và tỉ mỉ.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-anh-hung-biet-thu-nha-vuon-bac-ninh/gallery-09-09-09-thiet-ke-noi-that-biet-thu-nha-vuon-bac-ninh-anh-hung-3-ebda33cf.webp','right',8),('cmswx13vz000ilipnaakeh20g','cmswx13vt0000lipnlwb6rtwy','01','Câu chuyện thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-chi-thuy-biet-thu-cao-cap-kdt-splendora/cover-01-01-01-thiet-ke-thi-cong-noi-that-biet-thu-chi-thuy-1-d0c5fd90.webp','right',0),('cmswx13vz000jlipntxatj8dp','cmswx13vt0000lipnlwb6rtwy','02','Câu chuyện thiết kế','Chủ nhà yêu thích không gian mang hơi hướng tân cổ điển, phong cách hoàng gia sang trọng nên sự lựa chọn kết hợp giữa màu trắng nhẹ nhàng, tinh tế và màu vàng kim sang trọng, bắt mắt là vô cùng hoàn hảo.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-chi-thuy-biet-thu-cao-cap-kdt-splendora/gallery-02-02-02-thiet-ke-thi-cong-noi-that-biet-thu-chi-thuy-2-0abe1a86.webp','left',1),('cmswx13vz000klipnysfu2hz0','cmswx13vt0000lipnlwb6rtwy','03','Câu chuyện thiết kế','Những chi tiết trang trí vô cùng cầu kỳ như các họa tiết mạ vàng, họa tiết hoa hồng trên cửa sổ hay bức tranh phủ lớp hợp kim màu vàng đồng tạo nên vẻ sang trọng và ấn tượng cho không gian.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-chi-thuy-biet-thu-cao-cap-kdt-splendora/gallery-03-03-03-thiet-ke-thi-cong-noi-that-biet-thu-chi-thuy-5-514b9661.webp','right',2),('cmswx13vz000llipnonytz8mk','cmswx13vt0000lipnlwb6rtwy','04','Câu chuyện thiết kế','Những món đồ trang trí cầu kỳ, ghế bành họa tiết bọc vải sang trọng tô đậm nét cổ điển cho không gian. Rèm cửa hoa văn màu sắc rực rỡ tạo điểm nhấm màu sắc sinh động.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-chi-thuy-biet-thu-cao-cap-kdt-splendora/gallery-04-04-04-thiet-ke-thi-cong-noi-that-biet-thu-chi-thuy-6-46b1d4fa.webp','left',3),('cmswx13vz000mlipnlcxzz5b2','cmswx13vt0000lipnlwb6rtwy','05','Câu chuyện thiết kế','Không gian phòng ngủ thông thoáng và sáng sủa với hệ thống cửa sổ lớn tạo không gian mở thoáng đãng.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-chi-thuy-biet-thu-cao-cap-kdt-splendora/gallery-05-05-05-thiet-ke-thi-cong-noi-that-biet-thu-chi-thuy-4-356f873e.webp','right',4),('cmswx13vz000nlipn5t7nnc01','cmswx13vt0000lipnlwb6rtwy','06','Câu chuyện thiết kế','Không gian phòng ngủ sang trọng với màu vàng kim và trắng chủ đạo. Hệ thống ánh sáng đèn nhẹ nhàng, tạo cảm giác thư giãn và vô cùng phù hợp với không gian.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-chi-thuy-biet-thu-cao-cap-kdt-splendora/gallery-06-06-06-thiet-ke-thi-cong-noi-that-biet-thu-chi-thuy-3-8f7dee52.webp','left',5),('cmswx13vz000olipn9lqvszy2','cmswx13vt0000lipnlwb6rtwy','07','Câu chuyện thiết kế','Không có quá nhiều đồ nội thất hay đồ trang trí nhưng từng món đều khá cầu kỳ và sang trọng.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-chi-thuy-biet-thu-cao-cap-kdt-splendora/gallery-07-07-07-thiet-ke-thi-cong-noi-that-biet-thu-chi-thuy-7-e684bcdb.webp','right',6),('cmswx178s000klspnqspv97h2','cmswx178k0000lspn529zrmek','01','Câu chuyện thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-van-phong-duoc-pham-nano-khu-biet-thu-vuon-dao-lac-long-quan-tay-ho/cover-01-01-01-thiet-ke-kien-truc-noi-that-van-phong-duoc-pham-nano-cong-vao-1-fcb9957b.webp','right',0),('cmswx178s000llspnzddvco7s','cmswx178k0000lspn529zrmek','02','Câu chuyện thiết kế','Phần cổng vào được thiết kế khá ấn tượng. Không cần dùng biển hiệu như thông thường gây mất diện tích không gian phía trên, thay vì đó logo được đặt ngay trên nền cây xanh mướt trên cổng, vừa đẹp mắt lại thể hiện được tiêu chí hướng đến các sản phẩm thiên nhiên của công ty.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-van-phong-duoc-pham-nano-khu-biet-thu-vuon-dao-lac-long-quan-tay-ho/gallery-02-02-02-thiet-ke-kien-truc-noi-that-van-phong-duoc-pham-nano-san-vuon-1c4013e1.webp','left',1),('cmswx178s000mlspnomyporcb','cmswx178k0000lspn529zrmek','03','Câu chuyện thiết kế','Sân vườn được bố trí đẹp mắt với khung cảnh thiên nhiên như ở một resort sang trọng, cho cảm giác mát lành, dễ chịu. Đặc biệt, mảng tường cây với logo được cắt tỉa khéo léo từ cây cảnh vô cùng đẹp mắt. Hệ thống ánh sáng được bố trí thông minh, ấn tượng.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-van-phong-duoc-pham-nano-khu-biet-thu-vuon-dao-lac-long-quan-tay-ho/gallery-03-03-03-thiet-ke-kien-truc-noi-that-van-phong-duoc-pham-nano-sanh-1-1-b7c92c09.webp','right',2),('cmswx178s000nlspnhzedhs0o','cmswx178k0000lspn529zrmek','04','Câu chuyện thiết kế','Sảnh vào tạo cảm giác hài hòa, dễ chịu. Sử dụng gam màu trắng chủ đạo kết hợp cùng chất liệu gỗ và những điểm nhấn màu xanh lá cho ấn tượng về vẻ gần gũi với thiên nhiên.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-van-phong-duoc-pham-nano-khu-biet-thu-vuon-dao-lac-long-quan-tay-ho/gallery-04-04-04-thiet-ke-kien-truc-noi-that-van-phong-duoc-pham-nano-sanh-2-1-f420a11a.webp','left',3),('cmswx178s000olspniiwmyhpo','cmswx178k0000lspn529zrmek','05','Câu chuyện thiết kế','Bàn chờ thiết kế đơn giản với bàn gỗ và ghế chất liệu polime tổng hợp cao cấp. Chậu cây cảnh xinh xắn và lọ hoa để bàn tô điểm cho không gian thêm sinh động.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-van-phong-duoc-pham-nano-khu-biet-thu-vuon-dao-lac-long-quan-tay-ho/gallery-05-05-05-thiet-ke-kien-truc-noi-that-van-phong-duoc-pham-nano-sanh-3-1-89603a44.webp','right',4),('cmswx178s000plspnosolvi79','cmswx178k0000lspn529zrmek','06','Câu chuyện thiết kế','Kệ trưng bày sản phẩm với màu xanh mát mắt và bày thêm những chậu tiểu cảnh xinh xắn, phù hợp với sản phẩm chiết xuất thiên nhiên, tinh khiết, mát lành.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-van-phong-duoc-pham-nano-khu-biet-thu-vuon-dao-lac-long-quan-tay-ho/gallery-06-06-06-thiet-ke-kien-truc-noi-that-van-phong-duoc-pham-nano-sanh-4-258cdbcb.webp','left',5),('cmswx178s000qlspnn759gpd4','cmswx178k0000lspn529zrmek','07','Câu chuyện thiết kế','Quầy tiếp khách thiết kế đơn giản nhưng vô cùng đẹp mắt.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-van-phong-duoc-pham-nano-khu-biet-thu-vuon-dao-lac-long-quan-tay-ho/gallery-07-07-07-thiet-ke-kien-truc-noi-that-van-phong-duoc-pham-nano-phong-hop-1-1-7e0e83a0.webp','right',6),('cmswx178s000rlspnpiymhkw7','cmswx178k0000lspn529zrmek','08','Câu chuyện thiết kế','Phòng họp với nội thất đơn giản nhưng vô cùng tiện nghi. Hệ thống ánh sáng trần được bố trí khá thông minh, hiện đại.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-van-phong-duoc-pham-nano-khu-biet-thu-vuon-dao-lac-long-quan-tay-ho/gallery-08-08-08-thiet-ke-kien-truc-noi-that-van-phong-duoc-pham-nano-phong-hop-2-1-986b1dc3.webp','left',7),('cmswx178s000slspn5njcmgvs','cmswx178k0000lspn529zrmek','09','Câu chuyện thiết kế','Phòng họp sử dụng rèm cửa lá dọc, vừa tạo độ thông thoáng lại đảm bảo sự riêng tư cho các cuộc họp.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/du-an-van-phong-duoc-pham-nano-khu-biet-thu-vuon-dao-lac-long-quan-tay-ho/gallery-09-09-09-thiet-ke-kien-truc-noi-that-van-phong-duoc-pham-nano-phong-lam-viec-1-883db330.webp','right',8),('cmswx1b8g000mm1pnbm0l1pdk','cmswx1b890000m1pnlrbnq7u9','01','Câu chuyện thiết kế','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/cover-01-01-01-thiet-ke-biet-thu-1-scaled-c3d662a8.webp','right',0),('cmswx1b8g000nm1pnwel16w7y','cmswx1b890000m1pnlrbnq7u9','02','Hình ảnh thiết kế kiến trúc của căn nhà :','Lấy cảm hứng từ thiên nhiên, căn biệt thự được thiết kế phần kiến trúc với không gian hiện đại và gẫn gũi với thiên nhiên. Chúng tôi hiểu rằng môi trường sống là đièu kiện tiên quyết đối với mỗi gia đình.\n\nVì vậy kiến trúc sư của tổ ấm hoàn hảo luôn muốn những giá trị cốt lõi nhất của cuộc sống, những điều giản dị nhất và chân thật nhất được đưa vào từng nét vẽ, không quá hoa mỹ và bay bổng, chúng tôi thực tế trong từng nét bút, tỉ mỉ trong từng kích thước làm sao cho cân đối tầm nhìn không những thế vấn đề phong thủy cũng là khía cạnh được chúng tôi nghiên cứu rất sâu để đưa vào trong thiết kế.\n\nGia chủ sinh năm 1982 là tuổi nhâm tuất, Quẻ mệnh : nam, ly hỏa thuộc đông tứ mệnh. Chúng tôi chọn hướng nhà là hướng đông Nam.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/cover-01-01-01-thiet-ke-biet-thu-1-scaled-c3d662a8.webp','left',1),('cmswx1b8g000om1pnto1p5pu1','cmswx1b890000m1pnlrbnq7u9','03','Hình ảnh thiết kế kiến trúc của căn nhà :','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-03-02-02-thiet-ke-biet-thu-8-scaled-40678c44.webp','right',2),('cmswx1b8g000pm1pnmx4t7e16','cmswx1b890000m1pnlrbnq7u9','04','Hình ảnh thiết kế kiến trúc của căn nhà :','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-04-03-03-thiet-ke-biet-thu-13-scaled-760cca0e.webp','left',3),('cmswx1b8g000qm1pnbv1yf6yv','cmswx1b890000m1pnlrbnq7u9','05','Hình ảnh thiết kế kiến trúc của căn nhà :','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-05-04-04-thiet-ke-biet-thu-12-scaled-f8f390cc.webp','right',4),('cmswx1b8g000rm1pnr9uy6fa0','cmswx1b890000m1pnlrbnq7u9','06','Hình ảnh thiết kế kiến trúc của căn nhà :','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-06-05-05-thiet-ke-biet-thu-3-02ac517a.webp','left',5),('cmswx1b8g000sm1pn91vtvlxb','cmswx1b890000m1pnlrbnq7u9','07','Hình ảnh thiết kế kiến trúc của căn nhà :','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-07-06-06-thiet-ke-biet-thu-9-25ef6eb0.webp','right',6),('cmswx1b8g000tm1pnex5fg2id','cmswx1b890000m1pnlrbnq7u9','08','Hình ảnh thi công thực biệt thự tế của căn nhà trong quá trình thực hiện hoạt động các công tác thi công xây dựng.','Với kinh nghiệm nhiều năm trong ngành xây dựng, chúng tôi luôn đặt ra tiêu chí an toàn và chất lượng lên hàng đầu. Quá trình thi công biệt thự được diễn ra một cách bài bản với đầy đủ các biệt pháp khảo sát để đưa ra phương án, biệt pháp thi công phù hợp, an toàn và tiết kiệm nhưng vẫn đảm bảo được chất lượng và thẩm mỹ.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-08-07-07-thi-cong-biet-thu-9-7cd742df.webp','left',7),('cmswx1b8g000um1pnwa2gqzru','cmswx1b890000m1pnlrbnq7u9','09','Công tác giải phóng mặt bằng và đào móng.','Công tác giải phóng mặt bằng và đào móng được triển khai từ ngày 02/07/2022\n\nThay vì sử dụng phương pháp ép cọc ngay từ đầu như những đơn vị khác, ngay từ những ngày đầu trong quá trình thiết kế, thi công căn biệt thự AnsShoha Villa , chúng tôi đã khảo sát địa chất và đưa ra phương án chi tiết cho móng.\n\nDựa trên cơ sở địa chất chúng tôi chọn phương án thi công móng đơn ( cụ thể là móng cốc) Phương án này có ưu điểm là chi phí thấp chỉ bằng 30% so với chi phí làm móng cọc và 70% so với chi phí làm móng băng nhưng vẫn đảm bảo được tính an toàn cho công trình với điều kiện địa chất như của nhà gia chủ.\n\nChúng ta có một hệ thống móng vững chắc đồng thời chi phí tốt, điều này không nhiều đơn vị trên thị trường làm được.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-02-08-08-thi-cong-biet-thu-3-859222d9.webp','right',8),('cmswx1b8g000vm1pnfbhehucm','cmswx1b890000m1pnlrbnq7u9','10','Công tác đổ bê tông sàn tầng 1','Với mỗi căn nhà thì việc đổ bê tông sàn là một trong nhưng công tác quan trọng nhất vì vậy các kĩ sư làm việc tại công trường của tổ ấm hoàn hảo luôn tập trung và chú trong vào việc này hơn hết.\n\nVới những gia đình ở khí hậu nhiệt đới gió mùa, thì mỗi khi mưa đến sau đó là nắng thì sàn nhà hay bị ra mồ hôi, hiện tượng sàn nhà sau khi lát xong một thời gian bị phồng gạch lên … những hiện tượng sự cố đó chủ yếu đến từ việc thi công sàn không đảm bảo chất lượng cụ thể là công tác đổ bê tông sàn.','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-09-09-09-thi-cong-biet-thu-9-1-679b2c4f.webp','left',9),('cmswx1b8g000wm1pnv9mdp7l5','cmswx1b890000m1pnlrbnq7u9','11','Công tác đổ bê tông sàn tầng 1','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-10-10-10-thi-cong-biet-thu-8-4ce6d585.webp','right',10),('cmswx1b8g000xm1pnwj1vw9bo','cmswx1b890000m1pnlrbnq7u9','12','Công tác đổ bê tông sàn tầng 1','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-biet-thu-ansshohavilla/gallery-11-11-11-thi-cong-biet-thu-2-6fbcc7d5.webp','left',11),('cmswx1fr5000jmdpn6fpnuc8e','cmswx1fqz0000mdpn8d8tuqrm','01','Thông tin dự án','Địa điểm: Quảng Bình\n\nPhong cách thiết kế: Hiện đại\n\nDiện tích: 800m2','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-thiet-ke-biet-thu-mai-thai-800m2-quang-binh/cover-01-01-01-biet-thu-2-938a81d3.webp','right',0),('cmswx1fr5000kmdpncm4tzmot','cmswx1fqz0000mdpn8d8tuqrm','02','Hình ảnh thực tế đã thi công','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-thiet-ke-biet-thu-mai-thai-800m2-quang-binh/gallery-02-02-02-biet-thu-1-177e03d7.webp','left',1),('cmswx1fr5000lmdpnpwe4179d','cmswx1fqz0000mdpn8d8tuqrm','03','Hình ảnh thực tế đã thi công','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-thiet-ke-biet-thu-mai-thai-800m2-quang-binh/gallery-03-03-04-biet-thu-3-b3b9f037.webp','right',2),('cmswx1fr5000mmdpn0rex0ltf','cmswx1fqz0000mdpn8d8tuqrm','04','Hình ảnh thực tế đã thi công','','https://pub-b6d77d3bc0a843b0ae7d1e61de9c768b.r2.dev/web-moi/projects/thi-cong-thiet-ke-biet-